enum class TypedSlotRejectReason { StaticClassOvercommit, PinnedLaneConflict, ScoreboardReject, BankPendingReject, HardwareBudgetReject, AssistQuotaReject, AssistBackpressureReject, SpeculationBudgetReject, DomainReject, DynamicClassExhaustion, Other };
bool first(TypedSlotRejectReason reason) {		return (reason == TypedSlotRejectReason::StaticClassOvercommit || reason == TypedSlotRejectReason::PinnedLaneConflict);}
bool second(TypedSlotRejectReason reason) {		return (reason == TypedSlotRejectReason::ScoreboardReject || reason == TypedSlotRejectReason::BankPendingReject || reason == TypedSlotRejectReason::HardwareBudgetReject || reason == TypedSlotRejectReason::AssistQuotaReject || reason == TypedSlotRejectReason::AssistBackpressureReject || reason == TypedSlotRejectReason::SpeculationBudgetReject || reason == TypedSlotRejectReason::DomainReject || reason == TypedSlotRejectReason::DynamicClassExhaustion);}
int main() { using R=TypedSlotRejectReason; return !(first(R::StaticClassOvercommit) && first(R::PinnedLaneConflict) && !first(R::Other) && second(R::ScoreboardReject) && second(R::DomainReject) && !second(R::Other)); }